@click.group()
@click.version_option(version=_ab_version, prog_name="air-blackbox")
@click.pass_context
def main(ctx):
    """AIR Blackbox - AI governance control plane.

    Route your AI traffic through the gateway and get compliance,
    security, inventory, and incident response out of the box.
    """
    if ctx.invoked_subcommand not in ("--version", None, "discover"):
        print_banner()


@main.command()
def setup():
    """One-command setup: install the AI compliance model and verify everything works.

    This pulls the air-compliance model from Ollama registry and verifies
    the scanner is ready to use. Run this once after installing air-blackbox.

    Requirements: Ollama must be installed first (https://ollama.com)
    """
    import subprocess
    import shutil

    console.print(Panel.fit(
        "[bold cyan]AIR Blackbox Setup[/bold cyan]\n"
        "Setting up the AI compliance scanner...",
        border_style="cyan",
    ))

    # Step 1: Check Ollama
    console.print("\n[bold]Step 1/3:[/bold] Checking Ollama installation...")
    if shutil.which("ollama"):
        try:
            result = subprocess.run(["ollama", "--version"], capture_output=True, text=True, timeout=5)
            console.print(f"  [green]ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Â¦ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã¢â‚¬Å“[/green] Ollama installed: {result.stdout.strip()}")
        except Exception:
            console.print("  [green]ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Â¦ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã¢â‚¬Å“[/green] Ollama found")
    else:
        console.print("  [red]ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Â¦ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â[/red] Ollama not installed")
        console.print("\n  Install Ollama first:")
        console.print("    Mac:   [cyan]brew install ollama[/cyan]")
        console.print("    Linux: [cyan]curl -fsSL https://ollama.com/install.sh | sh[/cyan]")
        console.print("    All:   [cyan]https://ollama.com/download[/cyan]")
        console.print("\n  Then run [cyan]air-blackbox setup[/cyan] again.")
        return

    # Step 2: Pull model
    console.print("\n[bold]Step 2/3:[/bold] Pulling air-compliance model from registry...")
    console.print("  This downloads ~8GB (one-time). Grab a coffee.\n")

    try:
        result = subprocess.run(
            ["ollama", "pull", "airblackbox/air-compliance"],
            timeout=600,
        )
        if result.returncode == 0:
            # Create local alias
            subprocess.run(
                ["ollama", "cp", "airblackbox/air-compliance", "air-compliance"],
                capture_output=True, timeout=30,
            )
            console.print("  [green]ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Â¦ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã¢â‚¬Å“[/green] Model pulled and ready")
        else:
            console.print("  [red]ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Â¦ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â[/red] Failed to pull model")
            console.print("  Try manually: [cyan]ollama pull airblackbox/air-compliance[/cyan]")
            return
    except subprocess.TimeoutExpired:
        console.print("  [red]ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Â¦ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â[/red] Download timed out. Try: [cyan]ollama pull airblackbox/air-compliance[/cyan]")
        return

    # Step 3: Verify
    console.print("\n[bold]Step 3/3:[/bold] Verifying scanner...")
    try:
        result = subprocess.run(["ollama", "list"], capture_output=True, text=True, timeout=10)
        if "air-compliance" in result.stdout:
            console.print("  [green]ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Â¦ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã¢â‚¬Å“[/green] Model verified in Ollama")
        else:
            console.print("  [yellow]ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â [/yellow] Model pulled but not showing in list. Try restarting Ollama.")
    except Exception:
        # Best-effort verification; do not fail setup if this check errors
        console.print("  [yellow]ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â [/yellow] Could not verify model in Ollama (verification step failed).")

    console.print(Panel.fit(
        "[bold green]Setup complete![/bold green]\n\n"
        "Run your first scan:\n"
        "  [cyan]air-blackbox comply --scan .[/cyan]\n\n"
        "Or try the demo:\n"
        "  [cyan]air-blackbox demo[/cyan]",
        border_style="green",
    ))


@main.command()
@click.option("--gateway", default="http://localhost:8080", help="Gateway URL")
@click.option("--scan", default=".", help="Path to scan for code-level checks")
@click.option("--runs-dir", default=None, help="Path to .air.json records directory")
@click.option("--format", "fmt", type=click.Choice(["table", "json"]), default="table")
@click.option("--verbose", "-v", is_flag=True, help="Show detection type and fix hints")
@click.option("--deep", is_flag=True, default=False, hidden=True, help="(deprecated, now default) Run LLM deep analysis")
@click.option("--no-llm", is_flag=True, help="Skip LLM analysis, regex-only scan")
@click.option("--model", default="air-compliance", help="Ollama model for deep scan")
@click.option("--no-save", is_flag=True, help="Don't save results to compliance history")
@click.option("--standard", default="all", type=click.Choice(["eu", "us", "all"]), help="Jurisdiction: eu, us, or all")
def comply(gateway, scan, runs_dir, fmt, verbose, deep, no_llm, model, no_save, standard):
    """Check AI compliance across EU and US jurisdictions."""
    from air_blackbox.gateway_client import GatewayClient
    from air_blackbox.compliance.engine import run_all_checks
    std_label = {"eu": "EU AI Act", "us": "US State Laws", "all": "EU + US Jurisdictions"}[standard]
    console.print(f"\n[bold blue]AIR Blackbox[/] - {std_label} Compliance Check\n")
    with console.status("[bold green]Connecting to gateway..."):
        client = GatewayClient(gateway_url=gateway, runs_dir=runs_dir, scan_path=scan)
        status = client.get_status()
    if status.reachable:
        console.print(f"  [green]ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â[/] Gateway connected at [bold]{gateway}[/]")
    else:
        console.print(f"  [dim]ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¹ Gateway not running at {gateway} (optional - enables runtime checks)[/]")
    if status.total_runs > 0:
        src = "gateway" if status.reachable else "trust layer records"
        console.print(f"  [green]ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â[/] [bold]{status.total_runs:,}[/] logged events from {src} ({', '.join(status.models_observed[:3])})")
    else:
        console.print(f"  [yellow]ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â[/] No traffic data found")
    console.print(f"  [dim]Scanning: {scan}[/]\n")
    articles, detected_frameworks, rec_pkg, crosswalk_hint = run_all_checks(status, scan, standard=standard)

    # Hybrid mode: auto-run LLM analysis unless --no-llm
    deep_findings = []
    if not no_llm:
        from air_blackbox.compliance.deep_scan import deep_scan, _ollama_available, _model_available
        import os
        if _ollama_available() and _model_available(model):
            console.print(f"[bold]Running hybrid analysis (regex + AI model)...[/]\n")
            # Collect all Python files (supports single-file and directory scanning)
            py_files = []
            if os.path.isfile(scan) and scan.endswith(".py"):
                py_files = [os.path.abspath(scan)]
            else:
                skip_dirs = {"node_modules", ".git", "__pycache__", ".venv", "venv",
                             "dist", "build", ".eggs", "site-packages", ".tox",
                             ".mypy_cache", ".pytest_cache"}
                for root, dirs, files in os.walk(scan):
                    dirs[:] = [d for d in dirs if d not in skip_dirs and not d.endswith(".egg-info")]
                    for f in files:
                        if f.endswith(".py"):
                            py_files.append(os.path.join(root, f))
            total_files = len(py_files)

            # === Smart sampling: pick compliance-relevant files ===
            # Priority keywords - files most likely to contain compliance patterns
            priority_keywords = [
                "agent", "pipeline", "tool", "llm", "model", "chat",
                "safety", "guard", "policy", "policies", "hitl", "human",
                "trace", "tracing", "logging", "log", "audit", "monitor",
                "auth", "token", "scope", "permission", "identity",
                "validate", "validation", "schema", "pii", "redact",
                "retry", "fallback", "error", "exception", "handler",
                "inject", "sanitize", "filter", "boundary", "limit",
                "config", "settings", "core", "main", "app", "run",
            ]
            # Score and rank files by relevance
            def _score_file(fp):
                rel = os.path.relpath(fp, scan).lower()
                basename = os.path.basename(fp).lower()
                score = 0
                # Skip test files - they don't reflect compliance posture
                parts = rel.replace("\\", "/").split("/")
                if any(p in {"tests", "test", "testing"} for p in parts):
                    return -1
                if basename.startswith("test_") or basename == "conftest.py":
                    return -1
                # Boost files with compliance-relevant names
                for kw in priority_keywords:
                    if kw in basename:
                        score += 3
                    elif kw in rel:
                        score += 1
                # Boost core source files
                if any(p in {"src", "core", "lib", "components"} for p in parts):
                    score += 2
                # Boost larger files (more substance)
                try:
                    size = os.path.getsize(fp)
                    if size > 5000:
                        score += 2
                    elif size > 1000:
                        score += 1
                except OSError:
                    pass
                return score

            scored = [(fp, _score_file(fp)) for fp in py_files]
            scored = [(fp, s) for fp, s in scored if s >= 0]  # exclude tests
            scored.sort(key=lambda x: x[1], reverse=True)

            # Build code sample from top-ranked files
            # Cap individual files at 8KB to preserve full context, total at 48KB
            MAX_PER_FILE = 8000
            MAX_TOTAL = 48000
            code_parts = []
            total_chars = 0
            files_included = 0
            for fp, score in scored:
                try:
                    with open(fp, "r", encoding="utf-8", errors="ignore") as fh:
                        content = fh.read()
                    if len(content.strip()) < 50:
                        continue
                    # Truncate large files to get more variety in the sample
                    if len(content) > MAX_PER_FILE:
                        content = content[:MAX_PER_FILE] + "\n# ... (file truncated for sampling)"
                    code_parts.append(f"# File: {os.path.relpath(fp, scan)}\n{content}")
                    total_chars += len(content)
                    files_included += 1
                    if total_chars > MAX_TOTAL:
                        break
                except Exception:
                    continue

            merged_code = "\n\n".join(code_parts)
            sample_desc = f"targeted sample of {files_included} compliance-relevant source files"

            if verbose:
                console.print(f"  [dim]AI model sampling: {files_included} files from {total_files} total ({total_chars:,} chars)[/]")
                # Show top 5 sampled files
                shown = 0
                for fp, score in scored:
                    if shown >= 5:
                        break
                    rel = os.path.relpath(fp, scan)
                    try:
                        size = os.path.getsize(fp)
                        if size >= 50:
                            console.print(f"    [dim]score={score}: {rel} ({size:,} bytes)[/]")
                            shown += 1
                    except OSError:
                        pass
                if files_included > 5:
                    console.print(f"    [dim]... and {files_included - 5} more files[/]")

            # Build rule-based context summary for the model
            rule_context_lines = []
            article_map = {9: "Risk Management", 10: "Data Governance",
                          11: "Technical Documentation", 12: "Record-Keeping",
                          14: "Human Oversight", 15: "Accuracy & Security"}
            for article in articles:
                art_num = article.get("number", 0)
                if art_num not in article_map:
                    continue
                passes = []
                fails = []
                warns = []
                for check in article.get("checks", []):
                    name = check.get("name", "")
                    evidence = check.get("evidence", "")
                    status = check.get("status", "")
                    summary = f"{name}: {evidence[:80]}" if evidence else name
                    if status == "pass":
                        passes.append(summary)
                    elif status == "fail":
                        fails.append(summary)
                    elif status == "warn":
                        warns.append(summary)
                line = f"Article {art_num} ({article_map[art_num]}): "
                if passes:
                    line += f"{len(passes)} PASS ({'; '.join(passes[:2])})"
                if fails:
                    line += f", {len(fails)} FAIL" if passes else f"{len(fails)} FAIL"
                if warns:
                    line += f", {len(warns)} WARN" if (passes or fails) else f"{len(warns)} WARN"
                rule_context_lines.append(line)
            rule_context = "\n".join(rule_context_lines)

            # Only run AI model if we have actual code to analyze
            if files_included == 0 or not merged_code.strip():
                if verbose:
                    console.print(f"  [dim]No Python files found for AI analysis - skipping model[/]")
                result = {"available": False, "findings": [], "model": model, "error": None}
            else:
                if verbose:
                    os.environ["AIR_VERBOSE"] = "1"
                result = deep_scan(merged_code, model=model,
                                  sample_context=sample_desc,
                                  total_files=total_files,
                                  rule_context=rule_context)
                if verbose:
                    os.environ.pop("AIR_VERBOSE", None)
            if result.get("available") and not result.get("error"):
                deep_findings = result.get("findings", [])

                # ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ Smart reconciliation: override model FAIL when rule-based has strong PASS ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬
                # Build a map of rule-based pass counts per article
                rule_pass_counts = {}
                rule_evidence_map = {}
                for article in articles:
                    art_num = article.get("number", 0)
                    passes = [c for c in article.get("checks", []) if c.get("status") == "pass"]
                    rule_pass_counts[art_num] = len(passes)
                    if passes:
                        # Collect the best evidence summaries
                        rule_evidence_map[art_num] = "; ".join(
                            c.get("evidence", "")[:60] for c in passes[:3]
                        )

                overrides = 0
                for finding in deep_findings:
                    art = finding.get("article", 0)
                    model_status = finding.get("status", "")
                    rule_passes = rule_pass_counts.get(art, 0)

                    # If model says FAIL but rule-based has 2+ PASS checks ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ override to PASS
                    if model_status == "fail" and rule_passes >= 2:
                        finding["status"] = "pass"
                        rule_ev = rule_evidence_map.get(art, "")
                        finding["evidence"] = (
                            f"[Corrected by rule-based analysis] "
                            f"Rule-based scanner found {rule_passes} passing checks: {rule_ev}. "
                            f"Model's original assessment: {finding.get('evidence', '')}"
                        )
                        finding["fix_hint"] = ""
                        overrides += 1
                    # If model says FAIL but rule-based has 1 PASS ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ upgrade to WARN
                    elif model_status == "fail" and rule_passes == 1:
                        finding["status"] = "warn"
                        rule_ev = rule_evidence_map.get(art, "")
                        finding["evidence"] = (
                            f"[Partial - rule-based found evidence] {rule_ev}. "
                            f"Model noted: {finding.get('evidence', '')}"
                        )
                        overrides += 1

                console.print(f"  [green]ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â[/] AI model analyzed [bold]{files_included}[/] files ({total_chars:,} chars) from {total_files} total")
                console.print(f"  [green]ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â[/] AI model found [bold]{len(deep_findings)}[/] finding(s) using [bold]{model}[/]")
                if overrides > 0:
                    console.print(f"  [green]ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â[/] Smart reconciliation: [bold]{overrides}[/] model verdict(s) corrected by rule-based evidence")
                console.print(f"  [green]ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â[/] Hybrid mode: rule-based + AI analysis merged\n")
            elif result.get("error"):
                console.print(f"  [yellow]ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â[/] AI model: {result['error']}")
                console.print(f"  [dim]Falling back to regex-only scan[/]\n")
        else:
            if verbose:
                console.print(f"  [dim]AI model not available - using regex-only scan[/]")
                console.print(f"  [dim]Optional: install the local model - https://github.com/airblackbox/airblackbox/tree/main/model[/]\n")

    # Save to compliance history
    if not no_save:
        try:
            from air_blackbox.compliance.history import save_scan
            scan_id = save_scan(articles, scan_path=scan, version="1.6.3",
                                deep_findings=deep_findings if deep_findings else None)
            if verbose:
                console.print(f"  [dim]Saved to compliance history (scan #{scan_id})[/]\n")
        except Exception:
            # Don't break the scan if history save fails
            if verbose:
                console.print("  [dim]Could not save to compliance history[/]")

    if fmt == "json":
        import json
        output_data = articles
        if deep_findings:
            output_data = list(articles)  # shallow copy
            output_data.append({
                "number": 0,
                "title": "LLM Deep Analysis",
                "checks": [{
                    "name": f.get("name", ""),
                    "status": f.get("status", "warn"),
                    "evidence": f.get("evidence", ""),
                    "fix_hint": f.get("fix_hint", ""),
                    "tier": "static",
                    "detection": "auto",
                    "source": "llm",
                } for f in deep_findings],
            })
